        public string MaHocSinh  { get; set; } = "";
    }

    // ── LIFECYCLE ──
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo     = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
        _selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
        _selectedHocKy = await BrowserStorageService.GetItem(JS, "selectedHocKy");
        _currentHocKy = int.TryParse(_selectedHocKy, out var hk) ? hk : (int?)null;
        _prevHocKy = _currentHocKy.HasValue && _currentHocKy.Value > 1 ? _currentHocKy.Value - 1 : (int?)null;
        _canCopyFromPrevSemester = _prevHocKy.HasValue;
        _khoiList   = await TruongService.hGetDanhSachKhoi(_maTruongBo ?? "", _selectedCapHoc ?? "1");
        _allLopList = await TruongService.hGetDanhSachLop(_maTruongBo ?? "", _selectedCapHoc ?? "1", _selectedNamHoc ?? "");

        if (_khoiList.Any())
        {
            _selKhoiId   = _khoiList[0].MaKhoi;
            _lopFiltered = _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();
        }
        else _lopFiltered = _allLopList.ToList();

        if (_lopFiltered.Any())
        {
            var first      = _lopFiltered[0];
            _selLopId      = first.IdLopBo;
            _selLopMaLopBo = first.MaLopBo;
        }

        await LoadData();
    }

    private async Task LoadData()
    {
        UpdateSemesterState();
        _isLoading = true; StateHasChanged();
        try
        {
            int? hocKy = _currentHocKy;
            var taskHs    = string.IsNullOrEmpty(_selLopMaLopBo)
                                ? Task.FromResult(new List<HocSinhDTO>())
                                : TruongService.hGetHocSinhByLop(_maTruongBo ?? "", _selLopMaLopBo, _selectedNamHoc ?? "");
            var taskSoDo  = TruongService.hGetSoDoLopHoc(lopId: _selLopId, maHocKy: hocKy, namHoc: _selectedNamHoc);

            await Task.WhenAll(taskHs, taskSoDo);

            _allHsLop = taskHs.Result;
            var soDoList = taskSoDo.Result;
            _soDoDb = soDoList.FirstOrDefault(); // lấy bản ghi đầu (1 lớp / 1 bản ghi)

            // Parse JSON → grid
            if (_soDoDb != null && !string.IsNullOrEmpty(_soDoDb.SoDoLop))
            {
                ParseJsonToGrid(_soDoDb.SoDoLop);
            }
            else
            {
                // Chưa có → tạo grid trống mặc định
                BuildEmptyGrid(_rows, _cols);
            }

            RefreshUnassigned();
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isLoading = false; StateHasChanged(); }
    }

    // ── FILTER EVENTS ──
    private async Task OnKhoiChanged(ChangeEventArgs e)
    {
        _selKhoiId   = int.TryParse(e.Value?.ToString(), out var kv) ? kv : 0;
        _lopFiltered = _selKhoiId == 0
            ? _allLopList.ToList()
            : _allLopList.Where(l => l.MaKhoi == _selKhoiId).ToList();

        if (_lopFiltered.Any())
        {
            var first      = _lopFiltered[0];
            _selLopId      = first.IdLopBo;
            _selLopMaLopBo = first.MaLopBo;
        }
        else { _selLopId = 0; _selLopMaLopBo = ""; }
        _isEditMode = false;
        await LoadData();
    }

    private async Task OnLopChanged(ChangeEventArgs e)
    {
        _selLopId = int.TryParse(e.Value?.ToString(), out var lv) ? lv : 0;
        var lop   = _lopFiltered.FirstOrDefault(l => l.IdLopBo == _selLopId);
        _selLopMaLopBo = lop?.MaLopBo ?? "";
        _isEditMode = false;
        UpdateSemesterState();
        await LoadData();
    }

    private async Task OnHocKyChanged()
    {
        _isEditMode = false;
        UpdateSemesterState();
        await LoadData();
    }

    private void UpdateSemesterState()
    {
        _currentHocKy = int.TryParse(_selectedHocKy, out var hk) ? hk : (int?)null;
        _prevHocKy = _currentHocKy.HasValue && _currentHocKy.Value > 1 ? _currentHocKy.Value - 1 : (int?)null;
        _canCopyFromPrevSemester = _prevHocKy.HasValue;
    }

    // ── GRID HELPERS ──
    private void BuildEmptyGrid(int rows, int cols)
    {
        _rows = rows; _cols = cols;
        _grid = new();
        for (int h = 1; h <= rows; h++)
        {
            var row = new List<SoDoCell>();
            for (int c = 1; c <= cols; c++)
                row.Add(new SoDoCell { Hang = h, Cot = c });
            _grid.Add(row);
        }
    }

    private void ParseJsonToGrid(string json)
    {
        try
        {
            // JSON là array of arrays: [[{Cot,Hang,HoTen,MaHocSinh},...],...]
            var outerArr = JsonSerializer.Deserialize<List<List<JsonElement>>>(json);
            if (outerArr == null || !outerArr.Any()) { BuildEmptyGrid(_rows, _cols); return; }

            // Tìm max Hang, max Cot
            int maxH = 0, maxC = 0;
            var flatCells = new List<SoDoCell>();
            foreach (var innerArr in outerArr)
            {
                foreach (var el in innerArr)
                {
                    var cell = new SoDoCell
                    {
                        Cot        = el.GetProperty("Cot").GetInt32(),
                        Hang       = el.GetProperty("Hang").GetInt32(),
                        HoTen      = el.TryGetProperty("HoTen", out var ht) ? ht.GetString() ?? "" : "",
                        MaHocSinh  = el.TryGetProperty("MaHocSinh", out var mhs) ? mhs.GetString() ?? "" : "",
                    };
                    maxH = Math.Max(maxH, cell.Hang);
                    maxC = Math.Max(maxC, cell.Cot);
                    flatCells.Add(cell);
                }
            }

            _rows = maxH; _cols = maxC;
            _grid = new();
            for (int h = 1; h <= _rows; h++)
            {
                var row = new List<SoDoCell>();
                for (int c = 1; c <= _cols; c++)
                {
                    var found = flatCells.FirstOrDefault(x => x.Hang == h && x.Cot == c);
                    row.Add(found ?? new SoDoCell { Hang = h, Cot = c });
                }
                _grid.Add(row);
            }
        }
        catch { BuildEmptyGrid(_rows, _cols); }
    }

    private string SerializeGridToJson()
    {
        var opts = new JsonSerializerOptions { Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping };
        return JsonSerializer.Serialize(_grid.Select(row =>
            row.Select(c => new { c.Cot, c.Hang, c.HoTen, c.MaHocSinh })
        ), opts);
    }

    private SoDoCell? GetCell(int hang, int cot)
    {
        if (hang < 1 || hang > _grid.Count) return null;
        var row = _grid[hang - 1];
        if (cot < 1 || cot > row.Count) return null;
        return row[cot - 1];
    }

    private void RebuildGrid()
    {
        var old = _grid.SelectMany(r => r).Where(c => !string.IsNullOrEmpty(c.MaHocSinh)).ToList();
        BuildEmptyGrid(_rows, _cols);
        // Giữ lại HS cũ nếu vị trí vẫn còn trong grid
        foreach (var oldCell in old)
        {
            var cell = GetCell(oldCell.Hang, oldCell.Cot);
            if (cell != null) { cell.HoTen = oldCell.HoTen; cell.MaHocSinh = oldCell.MaHocSinh; }
        }
        RefreshUnassigned();
    }

    private void RefreshUnassigned()
    {
        var assigned = _grid.SelectMany(r => r).Where(c => !string.IsNullOrEmpty(c.MaHocSinh))
                            .Select(c => c.MaHocSinh).ToHashSet();
        _unassigned = _allHsLop.Where(h => !assigned.Contains(h.MaHsSo)).ToList();
    }

    // ── EDIT MODE ──
    private void EnterEditMode()
    {
        _backupJson = SerializeGridToJson();
        _backupRows = _rows; _backupCols = _cols;
        RefreshUnassigned();
        _selectedHs = null;
        _isEditMode = true;
    }

    private void CancelEdit()
    {
        // Khôi phục từ backup
        ParseJsonToGrid(_backupJson);
        _isEditMode = false;
        _selectedHs = null;
    }

    private void SelectHs(HocSinhDTO hs)
    {
        _selectedHs = _selectedHs?.MaHsSo == hs.MaHsSo ? null : hs;
    }

    private void HandleCellClick(int hang, int cot)
    {
        if (!_isEditMode) return;
        var cell = GetCell(hang, cot);
        if (cell == null) return;

        if (!string.IsNullOrEmpty(cell.MaHocSinh))
        {
            // Có HS → gỡ ra, đưa về danh sách chờ
            var hs = _allHsLop.FirstOrDefault(h => h.MaHsSo == cell.MaHocSinh);
            if (hs != null && !_unassigned.Any(u => u.MaHsSo == hs.MaHsSo))
                _unassigned.Add(hs);
            cell.HoTen = ""; cell.MaHocSinh = "";
            _selectedHs = null;
        }
        else if (_selectedHs != null)
        {
            // Trống + đang chọn HS → xếp vào
            cell.HoTen     = _selectedHs.HoTen;
            cell.MaHocSinh = _selectedHs.MaHsSo;
            _unassigned.RemoveAll(u => u.MaHsSo == _selectedHs.MaHsSo);
            _selectedHs = null;
        }
    }

    // ── SHUFFLE ──
    private void ShuffleAll()
    {
        if (!_allHsLop.Any()) return;
        // Clear grid
        foreach (var row in _grid) foreach (var c in row) { c.HoTen = ""; c.MaHocSinh = ""; }

        var rnd   = new Random();
        var shuffled = _allHsLop.OrderBy(_ => rnd.Next()).ToList();
        var cells = _grid.SelectMany(r => r).ToList();

        for (int i = 0; i < shuffled.Count && i < cells.Count; i++)
        {
            cells[i].HoTen     = shuffled[i].HoTen;
            cells[i].MaHocSinh = shuffled[i].MaHsSo;
        }
        StateHasChanged();
    }

    // ── SAVE ──
    private async Task SaveSoDo()
    {
        _isSaving = true; StateHasChanged();
        try
        {
            var json = SerializeGridToJson();
            if (_soDoDb == null)
            {
                _soDoDb = new ScnSoDoLopHocDTO
                {
                    Id       = 0,
                    KhoiId   = _selKhoiId,
                    LopId    = _selLopId,
                    SoDay   = _cols,
                    SoHang  = _rows,
                    SoDoLop = json,
                    NamHoc  = _selectedNamHoc,
                    MaHocKy = _currentHocKy,
                };
            }
            else
            {
                _soDoDb.SoDay   = _cols;
                _soDoDb.SoHang  = _rows;
                _soDoDb.SoDoLop = json;
                _soDoDb.NamHoc  = _selectedNamHoc;
                _soDoDb.KhoiId  = _selKhoiId;
                _soDoDb.LopId   = _selLopId;
                _soDoDb.MaHocKy = _currentHocKy;
            }

            await TruongService.hUpsertSoDoLopHoc(_soDoDb);
            _isEditMode = false;
            _selectedHs = null;
            await ShowToast("Đã lưu sơ đồ!", "toast-ok", "check_circle");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Da xay ra loi, vui long thu lai!", "toast-err", "error"); }
        finally { _isSaving = false; StateHasChanged(); }
    }

    private async Task CopyFromPreviousSemester()
    {
        if (!_prevHocKy.HasValue) return;
        _isLoading = true; StateHasChanged();
        try
        {
            var prevList = await TruongService.hGetSoDoLopHoc(lopId: _selLopId, maHocKy: _prevHocKy, namHoc: _selectedNamHoc);
            var prev = prevList.FirstOrDefault();
            if (prev == null || string.IsNullOrWhiteSpace(prev.SoDoLop))
            {
                await ShowToast($"Không tìm thấy sơ đồ của học kỳ {_prevHocKy}.", "toast-err", "error");
                return;
            }

            ParseJsonToGrid(prev.SoDoLop);
            _soDoDb ??= new ScnSoDoLopHocDTO();
            _soDoDb.Id = 0;
            _soDoDb.KhoiId = _selKhoiId;
            _soDoDb.LopId = _selLopId;
            _soDoDb.SoDay = _cols;
            _soDoDb.SoHang = _rows;
            _soDoDb.SoDoLop = SerializeGridToJson();
            _soDoDb.NamHoc = _selectedNamHoc;
            _soDoDb.MaHocKy = _currentHocKy;
            RefreshUnassigned();
            await ShowToast($"Đã sao chép sơ đồ từ học kỳ {_prevHocKy}.", "toast-ok", "content_copy");
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Không thể sao chép sơ đồ, vui lòng thử lại!", "toast-err", "error");
        }
        finally
        {
            _isLoading = false;
            StateHasChanged();
        }
    }

    // ── HELPERS ──
    private string GetAvatarUrl(string? maHocSinh)
    {
        if (string.IsNullOrWhiteSpace(_maTruongBo) || string.IsNullOrWhiteSpace(maHocSinh))
            return "../image/avtmacdinh.jpg";
        return $"https://face.titkul.com/ImageFace/{_maTruongBo}/{maHocSinh}.jpg";
    }

    /// Lấy tên cuối (họ tên ngắn gọn)
    private static string GetLastName(string? fullName)
    {
        if (string.IsNullOrEmpty(fullName)) return "—";
        var parts = fullName.Trim().Split(' ');
        return parts.Length <= 2 ? fullName : string.Join(" ", parts[^2..]);
    }

    private async Task ShowToast(string msg, string css, string icon)
    {
        _toastCts?.Cancel();
        _toastCts  = new System.Threading.CancellationTokenSource();
        _toastMsg  = msg; _toastCss = css; _toastIcon = icon;
        StateHasChanged();
        try { await Task.Delay(3500, _toastCts.Token); _toastMsg = ""; StateHasChanged(); }
        catch (TaskCanceledException) {}
    }

